func scratchAlloc(occupied bool, released *int) *mockCIDRAllocator {
	return &mockCIDRAllocator{
		OnInRange:     func(cidr *net.IPNet) bool { return true },
		OnIsFull:      func() bool { return false },
		OnIsAllocated: func(cidr *net.IPNet) (bool, error) { return occupied, nil },
		OnOccupy:      func(cidr *net.IPNet) error { return nil },
		OnRelease: func(cidr *net.IPNet) error {
			if released != nil {
				*released++
			}
			return nil
		},
	}
}

// Partial conflict: v4 free, v6 already allocated elsewhere.
func TestScratch_PartialConflict_reuseIPNets(t *testing.T) {
	var relV4, relV6 int
	n := &NodesPodCIDRManager{
		logger:              hivetest.Logger(t),
		canAllocatePodCIDRs: true,
		v4CIDRAllocators:    []cidralloc.CIDRAllocator{scratchAlloc(false, &relV4)},
		v6CIDRAllocators:    []cidralloc.CIDRAllocator{scratchAlloc(true, &relV6)},
		nodes:               map[string]*nodeCIDRs{},
	}
	res, allocated, err := n.reuseIPNets("node-1", mustNewCIDRs("10.10.0.0/24"), mustNewCIDRs("fd00::/80"))
	require.Error(t, err, "want conflict error")
	require.Contains(t, err.Error(), "already allocated")
	require.True(t, allocated, "want allocated=true")
	require.Equal(t, mustNewCIDRs("10.10.0.0/24"), res.v4PodCIDRs)
	require.Empty(t, res.v6PodCIDRs, "conflicting v6 must be stripped")
	require.Equal(t, 0, relV4, "kept v4 must NOT be released")
	// node stored with only v4
	require.Equal(t, map[string]*nodeCIDRs{
		"node-1": {v4PodCIDRs: mustNewCIDRs("10.10.0.0/24")},
	}, n.nodes)
}

// Both conflict: neither occupied, node not stored, allocated=false.
func TestScratch_BothConflict_reuseIPNets(t *testing.T) {
	n := &NodesPodCIDRManager{
		logger:              hivetest.Logger(t),
		canAllocatePodCIDRs: true,
		v4CIDRAllocators:    []cidralloc.CIDRAllocator{scratchAlloc(true, nil)},
		v6CIDRAllocators:    []cidralloc.CIDRAllocator{scratchAlloc(true, nil)},
		nodes:               map[string]*nodeCIDRs{},
	}
	res, allocated, err := n.reuseIPNets("node-1", mustNewCIDRs("10.10.0.0/24"), mustNewCIDRs("fd00::/80"))
	require.Error(t, err)
	require.False(t, allocated)
	require.Nil(t, res)
	require.Empty(t, n.nodes, "node must not be stored")
}

